const delay = ms => new Promise(r=>setTimeout(r,ms));
(async()=>{
const target=await(await fetch('http://127.0.0.1:9222/json/new?http://127.0.0.1:3002',{method:'PUT'})).json();
const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
let id=0;const pending=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id){pending.get(m.id)?.(m);pending.delete(m.id)}};
const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
const ev=async expression=>{const r=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});return r.result?.result?.value};
await call('Page.enable');await call('Runtime.enable');await call('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});await call('Page.navigate',{url:'http://127.0.0.1:3002'});await delay(1200);
let shot=await call('Page.captureScreenshot',{format:'png'});console.log('screenshot reply',Object.keys(shot),shot.error||'',shot.result&&Object.keys(shot.result));if(shot.result?.data)require('fs').writeFileSync('/tmp/opencode/sansad-mobile-menu.png',Buffer.from(shot.result.data,'base64'));
await ev(`document.querySelector('#playNow').click();document.querySelectorAll('.mode-pill')[3].click();document.querySelector('#continueBtn').click();document.querySelector('#startFight').click()`);await delay(1500);
const first=await ev(`({viewport:[innerWidth,innerHeight],timer:document.querySelector('#fightTimer').textContent,controls:getComputedStyle(document.querySelector('#mobileControls')).display,visible:!document.querySelector('#fightUI').classList.contains('hidden'),rect:(()=>{let r=document.querySelector('#mobileControls').getBoundingClientRect();return [r.x,r.y,r.width,r.height]})(),p:document.querySelector('#playerHealth').style.width,e:document.querySelector('#enemyHealth').style.width})`);
await ev(`(()=>{let b=document.querySelector('[data-action=punch]');b.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:1,pointerType:'touch',isPrimary:true}));})()`);await delay(500);await ev(`document.querySelector('[data-action=punch]').dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:1,pointerType:'touch',isPrimary:true}))`);
let after=await ev(`({timer:document.querySelector('#fightTimer').textContent,p:document.querySelector('#playerHealth').style.width,e:document.querySelector('#enemyHealth').style.width})`);
shot=await call('Page.captureScreenshot',{format:'png'});if(shot.result?.data)require('fs').writeFileSync('/tmp/opencode/sansad-mobile-fight.png',Buffer.from(shot.result.data,'base64'));
console.log(JSON.stringify({first,after},null,2));ws.close();
})();

