const delay = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
  const target = targets.find(t => t.type === 'page' && t.url.includes('127.0.0.1:3002'));
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise(resolve => ws.onopen = resolve);
  let id = 0; const pending = new Map(); const errors = [];
  ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id) { const p = pending.get(m.id); pending.delete(m.id); p?.(m); } else if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.text); else if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') errors.push(m.params.args.map(a => a.value || a.description).join(' ')); };
  const call = (method, params = {}) => new Promise(resolve => { const n = ++id; pending.set(n, resolve); ws.send(JSON.stringify({id:n,method,params})); });
  const ev = async expression => (await call('Runtime.evaluate', {expression, returnByValue:true, awaitPromise:true})).result?.result?.value;
  await call('Page.enable'); await call('Runtime.enable'); await call('Page.navigate', {url:'http://127.0.0.1:3002'}); await delay(1500);
  await ev(`document.querySelector('#playNow').click();document.querySelector('#continueBtn').click();document.querySelector('#startFight').click()`);
  let result = null;
  for(let i=0;i<100;i++){ await delay(1000); result=await ev(`({result:!document.querySelector('#resultOverlay').classList.contains('hidden'),title:document.querySelector('#resultTitle').textContent,timer:document.querySelector('#fightTimer').textContent,player:document.querySelector('#playerHealth').style.width,enemy:document.querySelector('#enemyHealth').style.width})`); if(result.result) break; }
  const rematchShown=await ev(`!document.querySelector('#resultOverlay').classList.contains('hidden')`);
  if(rematchShown) { await ev(`document.querySelector('#rematchBtn').click()`); await delay(500); }
  const rematch=await ev(`({resultHidden:document.querySelector('#resultOverlay').classList.contains('hidden'),fightVisible:!document.querySelector('#fightUI').classList.contains('hidden'),timer:document.querySelector('#fightTimer').textContent,player:document.querySelector('#playerHealth').style.width,enemy:document.querySelector('#enemyHealth').style.width,debugPresent:typeof window.__sansadDebug!=='undefined'})`);
  console.log(JSON.stringify({completion:result,rematch,errors},null,2)); ws.close();
})().catch(e=>{console.error(e);process.exit(1)});

